INSERT INTO qarar_governance.workflow_templates (id, organization_id, code, name_ar, name_en, description, status, created_by_user_id, created_at, updated_at) VALUES
	('3ce4be47-d567-46b9-a937-b1177b606617', '00000000-0000-0000-0000-000000000001', 'faculty_councils_regulation.university_trustees', 'مسار مجلس الجامعة ← مجلس الأمناء', NULL, 'مسار أجندة معتمد: مجلس الجامعة ثم مجلس الأمناء. الاعتماد الخارجي يسجل كمتطلب ولا ينفذ كاجتماع داخلي.', 'active', 'c9ba7429-a3ab-4088-9362-f04694f0687d', '2026-08-23 23:12:08.894416+00', '2026-08-23 23:12:08.894416+00'),
	('b0e8ccc0-5c82-41e9-a56d-e8760ecbfe12', '00000000-0000-0000-0000-000000000001', 'faculty_councils_regulation.conditional_higher_referral', 'مسار المجلس المختص ابتداءً ← المجلس الأعلى فقط إذا خرج الموضوع عن صلاحية المجلس أو اشترط النص اعتمادًا أعلى', NULL, 'مسار أجندة معتمد: المجلس المختص ابتداءً ثم المجلس الأعلى فقط إذا خرج الموضوع عن صلاحية المجلس أو اشترط النص اعتمادًا أعلى. الاعتماد الخارجي يسجل كمتطلب ولا ينفذ كاجتماع داخلي.', 'active', 'c9ba7429-a3ab-4088-9362-f04694f0687d', '2026-08-23 23:12:08.894416+00', '2026-08-23 23:12:08.894416+00'),
	('ed2410af-9431-4b2c-9cca-234995f4a516', '00000000-0000-0000-0000-000000000001', 'graduate_council_meeting_decision', 'اجتماع وقرار مجلس الدراسات العليا والبحث العلمي', NULL, 'مسار معياري يضمن إدراج الموضوع في جدول الأعمال، والتحقق من النصاب، والتصويت، وتوثيق القرار في المحضر.', 'active', 'c9ba7429-a3ab-4088-9362-f04694f0687d', '2026-08-23 23:12:08.894416+00', '2026-08-23 23:12:08.894416+00'),
	('1bab1811-9181-4f95-9b86-42b53d7fbe18', '00000000-0000-0000-0000-000000000001', 'graduate_studies_research_council_regulation.graduate_university', 'مسار مجلس الدراسات العليا والبحث العلمي ← مجلس الجامعة', NULL, 'مسار أجندة معتمد: مجلس الدراسات العليا والبحث العلمي ثم مجلس الجامعة. الاعتماد الخارجي يسجل كمتطلب ولا ينفذ كاجتماع داخلي.', 'active', 'c9ba7429-a3ab-4088-9362-f04694f0687d', '2026-08-23 23:12:08.894416+00', '2026-08-23 23:12:08.894416+00'),
	('a6b6e186-6578-4fb7-971b-99cc1f1d8f67', '00000000-0000-0000-0000-000000000001', 'graduate_studies_research_council_regulation.postgraduate_full', 'مسار مجلس القسم ← مجلس الكلية ← مجلس الدراسات العليا والبحث العلمي ← مجلس الجامعة عند اشتراط الاعتماد النهائي', NULL, 'مسار أجندة معتمد: مجلس القسم ثم مجلس الكلية ثم مجلس الدراسات العليا والبحث العلمي ثم مجلس الجامعة عند اشتراط الاعتماد النهائي. الاعتماد الخارجي يسجل كمتطلب ولا ينفذ كاجتماع داخلي.', 'active', 'c9ba7429-a3ab-4088-9362-f04694f0687d', '2026-08-23 23:12:08.894416+00', '2026-08-23 23:12:08.894416+00'),
